function svgicon(string $name):string{
$paths=['arrow'=>'<path d="M19 12H5m7 7-7-7 7-7"/>','code'=>'<path d="m8 17-5-5 5-5m8 0 5 5-5 5M14 4l-4 16"/>','server'=>'<rect x="3" y="3" width="18" height="8" rx="2"/><rect x="3" y="13" width="18" height="8" rx="2"/><path d="M7 7h.01M7 17h.01"/>','layers'=>'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>','briefcase'=>'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>','mail'=>'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 7 10 7 10-7"/>','spark'=>'<path d="m12 3 1.9 6.1L20 11l-6.1 1.9L12 19l-1.9-6.1L4 11l6.1-1.9L12 3ZM19 18v4m-2-2h4"/>','menu'=>'<path d="M4 7h16M4 12h16M4 17h16"/>','shopping'=>'<path d="M3 4h2l2 12h12l2-9H6M9 21h.01M18 21h.01"/>'];
return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'.($paths[$name]??$paths['layers']).'</svg>';
}
